/**
 * React wrapper (integration.md I2 item 4 — the last planned adapter): a thin
 * `<HangingStringsDiagramChart {...props}/>` that renders one container div and drives the
 * embeddable façade (I1/I4) through effects — mount → `createHangingStringsDiagram`, prop changes →
 * the façade's own setters (diffed per prop group, never a teardown/remount), unmount →
 * `destroy()`. Per I1 the wrapper never touches renderers; per I3 it maps nothing — the
 * canonical `categories`/`groups` are the props.
 *
 * Callbacks are wired once through stable refs (the façade takes them at creation), so
 * passing a new inline `onHover` every render neither re-creates the chart nor misses events.
 * `showHoverCard` and `height` are creation-time options; change them by remounting (`key`).
 *
 * No JSX and no react-dom: plain `createElement`, so the artifact stays dependency-thin —
 * its externals are `react` and the core.
 */

import { createElement, useEffect, useRef } from "react";
import type { CSSProperties, ReactElement } from "react";
import {
  createHangingStringsDiagram,
  type HangingStringsDiagram,
  type HangingStringsDiagramOptions,
} from "hanging-strings-diagram";

export interface HangingStringsDiagramChartProps extends HangingStringsDiagramOptions {
  /** Forwarded to the container div the chart mounts into. */
  className?: string;
  style?: CSSProperties;
}

/** Runs the effect on dependency CHANGES only, not on the initial mount — the mount effect
 * already created the façade with the initial props, so first-commit re-application would
 * just repeat work (theme/defs rebuilds, re-renders). */
function useUpdateEffect(effect: () => void, deps: unknown[]): void {
  const first = useRef(true);
  useEffect(() => {
    if (first.current) {
      first.current = false;
      return;
    }
    effect();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, deps);
}

export function HangingStringsDiagramChart(props: HangingStringsDiagramChartProps): ReactElement {
  const {
    categories,
    groups,
    railMode,
    theme,
    threadTexture,
    backdrop,
    colorMode,
    knobEncodesSecondMetric,
    showTicks,
    tickTarget,
    labelValues,
    stiffness,
    className,
    style,
  } = props;

  const containerRef = useRef<HTMLDivElement | null>(null);
  const hvRef = useRef<HangingStringsDiagram | null>(null);
  /** Latest render's props — the mount-time closure reads THROUGH this, so creation options
   * and callbacks always see current values without re-creating the chart. */
  const propsRef = useRef(props);
  propsRef.current = props;

  useEffect(() => {
    const p = propsRef.current;
    const hsd = createHangingStringsDiagram(containerRef.current as HTMLDivElement, {
      categories: p.categories,
      groups: p.groups,
      railMode: p.railMode,
      theme: p.theme,
      threadTexture: p.threadTexture,
      backdrop: p.backdrop,
      colorMode: p.colorMode,
      knobEncodesSecondMetric: p.knobEncodesSecondMetric,
      showTicks: p.showTicks,
      tickTarget: p.tickTarget,
      labelValues: p.labelValues,
      stiffness: p.stiffness,
      height: p.height,
      showHoverCard: p.showHoverCard,
      onSelect: (groupId) => propsRef.current.onSelect?.(groupId),
      onReorder: (event) => propsRef.current.onReorder?.(event),
      onExpand: (event) => propsRef.current.onExpand?.(event),
      onHover: (event) => propsRef.current.onHover?.(event),
    });
    hvRef.current = hsd;
    return () => {
      hvRef.current = null;
      hsd.destroy();
    };
  }, []);

  useUpdateEffect(() => {
    hvRef.current?.update({ categories, groups });
  }, [categories, groups]);

  useUpdateEffect(() => {
    if (railMode) hvRef.current?.setRailMode(railMode);
  }, [railMode]);

  useUpdateEffect(() => {
    if (theme !== undefined) hvRef.current?.setTheme(theme);
  }, [theme]);

  useUpdateEffect(() => {
    hvRef.current?.setThreadTexture(threadTexture ?? null);
  }, [threadTexture]);

  useUpdateEffect(() => {
    if (backdrop) hvRef.current?.setBackdrop(backdrop);
  }, [backdrop]);

  useUpdateEffect(() => {
    hvRef.current?.setOptions({
      ...(colorMode !== undefined ? { colorMode } : {}),
      ...(knobEncodesSecondMetric !== undefined ? { knobEncodesSecondMetric } : {}),
      ...(showTicks !== undefined ? { showTicks } : {}),
      ...(tickTarget !== undefined ? { tickTarget } : {}),
      ...(labelValues !== undefined ? { labelValues } : {}),
      ...(stiffness !== undefined ? { stiffness } : {}),
    });
  }, [colorMode, knobEncodesSecondMetric, showTicks, tickTarget, labelValues, stiffness]);

  return createElement("div", { ref: containerRef, className, style });
}
